// ---------------------------------------------------------------------------
// CSV export
// CSV columns (fixed order): merchant_id,order_id,currency,captured_minor,
// refunded_minor,fee_minor,chargeback_minor,net_minor,available_minor
// A field is quoted only when it contains a comma, a double quote or a line
// break; inner double quotes are doubled. Numbers are emitted verbatim.
// Rows follow the already-sorted `result.orders` order. Line separator is LF.
const CSV_COLUMNS = [
  'merchant_id',
  'order_id',
  'currency',
  ...MONEY_KEYS,
];

function csvField(value) {
  const s = value === undefined || value === null ? '' : String(value);
  if (/[",\r\n]/.test(s)) return `"${s.replaceAll('"', '""')}"`;
  return s;
}

export function toCsv(result) {
  const orders = Array.isArray(result?.orders) ? result.orders : [];
  const lines = [CSV_COLUMNS.join(',')];
  for (const order of orders) {
    lines.push(CSV_COLUMNS.map((col) => csvField(order?.[col])).join(','));
  }
  return `${lines.join('\n')}\n`;
}
EOF
