{"content":"import {toCsv} from '../ledger.mjs';

// Minimal RFC4180-style parser for round-trip verification.
function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQ = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQ) {
      if (ch === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else inQ = false;
      } else field += ch;
    } else if (ch === '"') inQ = true;
    else if (ch === ',') { row.push(field); field = ''; }
    else if (ch === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
    else field += ch;
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row); }
  return rows;
}

const cases = [
  ['a,b', 'plain'],
  ['he said "hi"', 'x'],
  ['x', 'line\nbreak'],
  ['x', 'cr\rlf'],
  ['x', 'both ",\n end'],
  ['comma,quote"and\nnewline', 'v'],
  ['', ''],
  ['trailing space ', ' lead'],
  ['"""', '""'],
];

let pass = 0;
for (const [m, o] of cases) {
  const order = {
    merchant_id: m, order_id: o, currency: 'CNY',
    captured_minor: 1, refunded_minor: 0, fee_minor: 0,
    chargeback_minor: 0, net_minor: 1, available_minor: 1, status: 'paid',
  };
  const rows = parseCsv(toCsv({orders: [order]}));
  const dataRow = rows[1];
  const ok = dataRow[0] === m && dataRow[1] === o;
  if (ok) pass++;
  console.log(ok ? 'PASS' : 'FAIL', JSON.stringify([m, o]), '->', JSON.stringify(dataRow.slice(0, 2)));
}
console.log(`${pass}/${cases.length} round-trip cases pass`);
","path":"notes/csv-roundtrip.mjs"}

