{"content":"#!/usr/bin/env node
// Offline order-ledger auditor CLI (no dependencies).
//
// Usage:
//   node cli.mjs input.json              -> JSON result on stdout
//   node cli.mjs input.json output.json  -> JSON result written to output.json
//
// The input file must be a JSON object of the shape {events, options}.
// `events` defaults to [] and `options` to {} when omitted.
//
// Exit codes: 0 success, 1 invalid input / options / IO error.
// On failure a JSON object {error, code?} is written to stderr and nothing is
// written to stdout or to the output file.

import {readFile, writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import {reconcile} from './ledger.mjs';

const USAGE = 'usage: node cli.mjs input.json [output.json]';

function fail(message, code) {
  const payload = code ? {error: message, code} : {error: message};
  process.stderr.write(`${JSON.stringify(payload)}\n`);
  process.exit(1);
}

function parseArgs(argv) {
  const args = argv.slice(2).filter((a) => a !== '');
  if (args.length < 1 || args.length > 2) fail(USAGE, 'USAGE');
  return {inputPath: args[0], outputPath: args[1]};
}

async function readInput(inputPath) {
  let raw;
  try {
    raw = await readFile(resolve(inputPath), 'utf8');
  } catch (e) {
    fail(`cannot read input file: ${inputPath}`, 'INPUT_READ');
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    fail(`input is not valid JSON: ${e.message}`, 'INPUT_JSON');
  }

  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fail('input must be a JSON object with "events" and/or "options"', 'INPUT_SHAPE');
  }
  return parsed;
}

async function main() {
  const {inputPath, outputPath} = parseArgs(process.argv);
  const input = await readInput(inputPath);

  const events = 'events' in input ? input.events : [];
  const options = 'options' in input ? input.options : {};

  if (events !== undefined && events !== null && !Array.isArray(events)) {
    fail('"events" must be an array', 'INPUT_SHAPE');
  }

  let result;
  try {
    result = reconcile(events ?? [], options ?? {});
  } catch (e) {
    // Contract-mandated option errors keep their INVALID_OPTIONS code.
    fail(String(e && e.message ? e.message : e), e && e.code ? e.code : 'RECONCILE_ERROR');
  }

  const json = `${JSON.stringify(result, null, 2)}\n`;

  if (outputPath === undefined) {
    process.stdout.write(json);
    return;
  }

  try {
    await writeFile(resolve(outputPath), json, 'utf8');
  } catch (e) {
    fail(`cannot write output file: ${outputPath}`, 'OUTPUT_WRITE');
  }
}

await main();
","path":"cli.mjs"}

