{"content":"// Regression harness: strict input-immutability + behaviour consistency.
// Deep-freezes events/options so ANY mutation attempt throws in strict mode,
// then verifies reconcile/toCsv/summarizeReports agree with the unfrozen run.

import assert from 'node:assert/strict';
import {reconcile, toCsv, summarizeReports} from '../ledger.mjs';

function deepFreeze(value, seen = new WeakSet()) {
  if (value === null || typeof value !== 'object') return value;
