{"content":"// Verify the 72h default window, inclusive boundary, and that batches audited
// under the old policy still reproduce their recorded (48h) results only when
// the recorded window is passed explicitly.
import {reconcile} from '../ledger.mjs';

const E = (id, type, amt, at) => ({
  id, merchant_id: 'm1', order_id: 'o1', currency: 'CNY', type, amount_minor: amt, at,
});

const captureAt = '2026-01-01T00:00:00Z';
const at = (h) => new Date(Date.parse(captureAt) + h * 3600 * 1000).toISOString().replace('.000Z', 'Z');

function run(label, refundAt, options) {
  const r = reconcile([E('c', 'capture', 1000, captureAt), E('r', 'refund', 100, refundAt)], options);
  const code = r.rejected[0]?.code ?? 'ACCEPTED';
  console.log(label.padEnd(46), code, '| refunded:', r.totals.refunded_minor);
  return code;
}

let bad = 0;
const expect = (label, actual, want) => {
  if (actual !== want) { bad++; console.log('  ^^ EXPECTED', want); }
};

// New default: 72h inclusive.
expect('48h', run('default @ +48h (inside new window)', at(48)), 'ACCEPTED');
expect('71h', run('default @ +71h', at(71)), 'ACCEPTED');
expect('72h exact', run('default @ +72h (boundary inclusive)', at(72)), 'ACCEPTED');
expect('72h+1s', run('default @ +72h + 1s', at(72) .replace('00Z','01Z')), 'REFUND_WINDOW');

// Explicit old policy still works (72h+ is out, 48h is in).
expect('explicit48@48', run('explicit 48h @ +48h', at(48), {refund_window_hours: 48}), 'ACCEPTED');
expect('explicit48@49', run('explicit 48h @ +49h', at(49), {refund_window_hours: 48}), 'REFUND_WINDOW');
expect('explicit72@72', run('explicit 72h @ +72h', at(72), {refund_window_hours: 72}), 'ACCEPTED');

console.log(bad === 0 ? 'WINDOW CHECKS OK' : `${bad} WINDOW CHECK FAILURES`);
if (bad) process.exit(1);
","path":"notes/window-72h-check.mjs"}

{"command":"cd <TEMP_ROOT>/native/workspace && node -e '
import("./ledger.mjs").then(async ({reconcile})=>{
const fs=require("fs");
const files=fs.readdirSync("batches").filter(f=>/^B0\d\d\.json$/.test(f)).sort();
let allMatchOld=true, anyDiffersNew=false;
for(const f of files){
  const b=JSON.parse(fs.readFileSync("batches/"+f,"utf8"));
  const rep=JSON.parse(fs.readFileSync("reports/"+f.replace(/\.json$/,"")+".json","utf8"));
  // (2) replay with the batch-recorded policy (48h explicit)
  const oldOpts={...b.options, refund_window_hours:48};
  const oldRun=reconcile(b.events, oldOpts);
  const sameOld=JSON.stringify(oldRun)===JSON.stringify(rep.result);
  // (3) recompute with NEW default (72h) -> should differ for batches with window-boundary cases
  const newOpts={...b.options}; delete newOpts.refund_window_hours; // let default apply
  const newRun=reconcile(b.events, newOpts);
  const sameNew=JSON.stringify(newRun)===JSON.stringify(rep.result);
  if(!sameOld) allMatchOld=false;
  if(!sameNew) anyDiffersNew=true;
  console.log(f, "| matches recorded 48h replay:", sameOld, "| new-72h default would change it:", !sameNew,
    sameNew?"":"| delta refunded:", newRun.totals.refunded_minor-rep.result.totals.refunded_minor,
    sameNew?"":"accepted:"+(newRun.accepted_ids.length-rep.result.accepted_ids.length));
}
console.log("\nAll old reports reproduce under their recorded 48h policy:", allMatchOld);
console.log("New 72h default would have changed at least one old batch:", anyDiffersNew);
})'"}

