{"command":"cd <TEMP_ROOT>/native/workspace && node -e '
const fs=require("fs");
const batches=fs.readdirSync("batches").filter(f=>/^B\d{3}\.json$/.test(f)).sort();
const reports=fs.readdirSync("reports").filter(f=>/^B\d{3}\.json$/.test(f)).sort();
console.log("batches:",batches.length,"reports:",reports.length,"1:1 match:",JSON.stringify(batches)===JSON.stringify(reports));
const ks=["captured_minor","refunded_minor","fee_minor","chargeback_minor","net_minor","available_minor"];
const tot=Object.fromEntries(ks.map(k=>[k,0]));
const ops={};
for(const f of reports){
  const rep=JSON.parse(fs.readFileSync("reports/"+f,"utf8"));
  for(const k of ks) tot[k]+=rep.result.totals[k];
  const key=rep.policy_version+" | "+rep.operational.reviewer+" | "+rep.operational.approval_gate+" | "+rep.operational.backup_days+"d | "+rep.operational.channel;
  (ops[key]=ops[key]||[]).push(rep.batch_id);
}
console.log("\n=== aggregate over 48 reports:");
console.log(JSON.stringify(tot,null,1));
console.log("net check:",tot.captured_minor-tot.refunded_minor-tot.chargeback_minor-tot.fee_minor===tot.net_minor);
console.log("\n=== operational snapshot distribution:");
for(const [k,v] of Object.entries(ops)) console.log("  "+k+"  -> "+v.length+" reports ("+v[0]+".."+v[v.length-1]+")");
const totalOrders=reports.reduce((a,f)=>a+JSON.parse(fs.readFileSync("reports/"+f,"utf8")).result.orders.length,0);
console.log("\ntotal order groups across all reports:",totalOrders);
'"}

