{"command":"cd <TEMP_ROOT>/native/workspace && node -e '
import("./ledger.mjs").then(async ({reconcile})=>{
const fs=await import("node:fs");
const files=fs.readdirSync("batches").filter(f=>/^B\d{3}\.json$/.test(f)).sort();
const ks=["captured_minor","refunded_minor","fee_minor","chargeback_minor","net_minor","available_minor"];
let unstable=[], mutated=[], frozenThrew=[];
function deepFreeze(v,seen=new WeakSet()){if(v===null||typeof v!=="object"||seen.has(v))return v;seen.add(v);Object.freeze(v);for(const k of Reflect.ownKeys(v))deepFreeze(v[k],seen);return v;}

for(const f of files){
  const raw=fs.readFileSync("batches/"+f,"utf8");
  const before=raw;
  const b=JSON.parse(raw);
  const snap=JSON.stringify(b);

  // (1) run 3 times on same (mutable) object; outputs must be identical
  const a1=JSON.stringify(reconcile(b.events,b.options));
  const a2=JSON.stringify(reconcile(b.events,b.options));
  const a3=JSON.stringify(reconcile(b.events,b.options));
  if(!(a1===a2&&a2===a3)) unstable.push(f);
  // (2) inputs must be untouched by those runs
  if(JSON.stringify(b)!==snap) mutated.push(f+":object");

  // (3) deep-frozen run must give identical output and not throw
  const fb=JSON.parse(JSON.stringify(b));
  deepFreeze(fb);
  try{
    const frozenOut=JSON.stringify(reconcile(fb.events,fb.options));
    if(frozenOut!==a1) unstable.push(f+":frozen-differs");
  }catch(e){ frozenThrew.push(f+":"+e.message); }

  // (4) raw file bytes on disk unchanged
  if(fs.readFileSync("batches/"+f,"utf8")!==before) mutated.push(f+":file");
}
console.log("batches:",files.length);
