finalArtifacts.ledger.mjs:
// Offline order-ledger auditor.
// Stage 1 (published): reconcile(events, options={}) basic capture aggregation
// and the mandated result shape; empty input yields zeros.
// All validation/normalisation helpers below follow the contract ordering so
// later stages can extend them without changing the public shape.

const TYPES = new Set(['capture', 'refund', 'fee', 'chargeback']);
const MONEY_KEYS = ['captured_minor', 'refunded_minor', 'fee_minor', 'chargeback_minor', 'net_minor', 'available_minor'];

const DEFAULTS = {
  fee_bps: 0,
  reserve_bps: 0,
  // Default refund window changed 48h -> 72h (POLICY_ROTATION_30).
  // Batches audited under the old policy keep their recorded 48h snapshot.
  refund_window_hours: 72,
  allowed_currencies: ['CNY'],
};

function invalidOptions(detail) {
  const err = new Error(`INVALID_OPTIONS: ${detail}`);
  err.code = 'INVALID_OPTIONS';
  return err;
}

function isPlainObject(v) {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function isBps(v, max) {
  return Number.isInteger(v) && v >= 0 && v <= max;
}

function normalizeOptions(options) {
  if (options === undefined || options === null) options = {};
  if (!isPlainObject(options)) throw invalidOptions('options must be an object');

  const opts = {...DEFAULTS};

  if ('fee_bps' in options) {
    if (!isBps(options.fee_bps, 10000)) throw invalidOptions('fee_bps must be an integer in [0,10000]');
    opts.fee_bps = options.fee_bps;
  }
  if ('reserve_bps' in options) {
    if (!isBps(options.reserve_bps, 10000)) throw invalidOptions('reserve_bps must be an integer in [0,10000]');
    opts.reserve_bps = options.reserve_bps;
  }
  if ('refund_window_hours' in options) {
    const w = options.refund_window_hours;
    // The contract requires a strictly positive window.
    if (typeof w !== 'number' || !Number.isFinite(w) || w <= 0) {
      throw invalidOptions('refund_window_hours must be a positive number');
    }
    opts.refund_window_hours = w;
  }
  if ('allowed_currencies' in options) {
    const c = options.allowed_currencies;
    if (!Array.isArray(c) || c.length === 0 || !c.every(x => typeof x === 'string' && x.length > 0)) {
      throw invalidOptions('allowed_currencies must be a non-empty array of strings');
    }
    // Currencies are normalised the same way as event values: trim + uppercase.
    opts.allowed_currencies = c.map(normalizeCurrency);
  }
  // An option that is explicitly present must carry a valid value: `undefined`
  // is not treated as "omitted" (consistent across all options).
  if ('allowed_merchants' in options) {
    const m = options.allowed_merchants;
    if (!Array.isArray(m) || !m.every(x => typeof x === 'string')) {
      throw invalidOptions('allowed_merchants must be an array of strings');
    }
    // Merchant ids are compared after trimming on both sides, so an allow-list
    // entry with stray whitespace cannot silently reject a valid merchant.
    opts.allowed_merchants = m.map((x) => x.trim());
  }
  if ('as_of' in options) {
    const t = parseTime(options.as_of);
    if (t === null) throw invalidOptions('as_of must be an ISO-8601 timestamp');
    opts.as_of = t;
  }
  return opts;
}

// Strict ISO-8601 with a mandatory timezone designator.
// Shape: YYYY-MM-DDTHH:mm[:ss[.fff]] followed by "Z"/"z" or ±HH:MM / ±HHMM.
// Calendar components are range-checked and the date must really exist, so
// lenient Date.parse fallbacks ("Jan 1 2026 ...Z", "2026-02-30...") are refused.
const ISO_RE = /^(\d{4})-(\d{2})-(\d{2})[Tt](\d{2}):(\d{2})(?::(\d{2})(?:\.(\d{1,9}))?)?(?:([Zz])|([+-])(\d{2}):?(\d{2}))$/;

function parseTime(value) {
  if (typeof value !== 'string') return null;
  const s = value.trim();
  const m = ISO_RE.exec(s);
  if (!m) return null;

  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  const hour = Number(m[4]);
  const minute = Number(m[5]);
  const second = m[6] === undefined ? 0 : Number(m[6]);
  const millis = m[7] === undefined ? 0 : Number(m[7].padEnd(3, '0').slice(0, 3));

  if (month < 1 || month > 12) return null;
  if (day < 1 || day > 31) return null;
  if (hour > 23 || minute > 59 || second > 59) return null;

  // Reject impossible calendar dates (e.g. Feb 30) via UTC round-trip.
  const ms = Date.UTC(year, month - 1, day, hour, minute, second, millis);
  const back = new Date(ms);
  if (
    back.getUTCFullYear() !== year ||
    back.getUTCMonth() !== month - 1 ||
    back.getUTCDate() !== day
  ) return null;

  let offsetMinutes = 0;
  if (!m[8]) {
    const offH = Number(m[10]);
    const offM = Number(m[11]);
    if (offH > 23 || offM > 59) return null;
    offsetMinutes = (offH * 60 + offM) * (m[9] === '-' ? -1 : 1);
  }

  return ms - offsetMinutes * 60 * 1000;
}

function trimId(value) {
  return typeof value === 'string' ? value.trim() : '';
}

// Currency codes are case-insensitive on input: trim, then uppercase.
// Identifier fields (id / merchant_id / order_id) are only trimmed and stay
// case-sensitive.
function normalizeCurrency(value) {
  return typeof value === 'string' ? value.trim().toUpperCase() : value;
}

const ZERO_TOTALS = () => ({
  captured_minor: 0,
  refunded_minor: 0,
  fee_minor: 0,
  chargeback_minor: 0,
  net_minor: 0,
  available_minor: 0,
});

// Exact floor(value * bps / 10000) for non-negative integer inputs.
// The intermediate product can exceed Number.MAX_SAFE_INTEGER (e.g. near-max
// amounts with high bps), where plain number arithmetic loses precision and
// skews the floor by +/-1 minor unit. BigInt keeps it exact.
function floorBps(value, bps) {
  if (bps === 0 || value <= 0) return 0;
  if (Number.isSafeInteger(value) && value * bps <= Number.MAX_SAFE_INTEGER) {
    return Math.floor((value * bps) / 10000);
  }
  return Number((BigInt(value) * BigInt(bps)) / 10000n);
}

function reserveFor(net, reserve_bps) {
  if (net <= 0) return 0;
  return floorBps(net, reserve_bps);
}

function finalizeAmounts(rec, reserve_bps) {
  rec.net_minor = rec.captured_minor - rec.refunded_minor - rec.chargeback_minor - rec.fee_minor;
  rec.available_minor = rec.net_minor - reserveFor(rec.net_minor, reserve_bps);
  return rec;
}

// Validate one event in the contract's mandated order. Returns {ok, ...} or {code}.
// Order: INVALID_ID -> INVALID_TYPE -> INVALID_AMOUNT -> INVALID_TIME ->
//        UNSUPPORTED_CURRENCY -> UNSUPPORTED_MERCHANT.
// Structural problems with any identifier field (id / merchant_id / order_id:
// absent, non-string, or empty after trim) are INVALID_ID and checked first;
// only a well-formed merchant that fails the allow-list is UNSUPPORTED_MERCHANT.
function validateEvent(ev, opts) {
  const raw = isPlainObject(ev) ? ev : {};
  const eventId = trimId(raw.id);

  const idRaw = raw.id;
  if (typeof idRaw !== 'string' || idRaw.trim() === '') return {code: 'INVALID_ID', event_id: eventId};
  const id = idRaw.trim();

  // Identifier fields are validated before type/amount/time.
  const merchantRaw = raw.merchant_id;
  if (typeof merchantRaw !== 'string' || merchantRaw.trim() === '') {
    return {code: 'INVALID_ID', event_id: eventId};
  }
  const merchant = merchantRaw.trim();

  const orderRaw = raw.order_id;
  if (typeof orderRaw !== 'string' || orderRaw.trim() === '') {
    return {code: 'INVALID_ID', event_id: eventId};
  }
  const orderId = orderRaw.trim();

  if (typeof raw.type !== 'string' || !TYPES.has(raw.type)) return {code: 'INVALID_TYPE', event_id: id, id};
  const type = raw.type;

  // Must be a safe positive integer. Strings ("100"), floats (1.25), negatives,
  // NaN/Infinity, -0 and unsafe integers are all rejected, never coerced.
  const amount = raw.amount_minor;
  if (typeof amount !== 'number' || !Number.isSafeInteger(amount) || amount <= 0) {
    return {code: 'INVALID_AMOUNT', event_id: id, id};
  }

  const at = parseTime(raw.at);
  if (at === null) return {code: 'INVALID_TIME', event_id: id, id};

  const currencyRaw = raw.currency;
  if (typeof currencyRaw !== 'string' || currencyRaw.trim() === '') return {code: 'UNSUPPORTED_CURRENCY', event_id: id, id};
  const currency = normalizeCurrency(currencyRaw);
  if (!opts.allowed_currencies.includes(currency)) {
    return {code: 'UNSUPPORTED_CURRENCY', event_id: id, id};
  }

  if (opts.allowed_merchants && !opts.allowed_merchants.includes(merchant)) {
    return {code: 'UNSUPPORTED_MERCHANT', event_id: id, id};
  }

  return {ok: true, id, type, amount, at, currency, merchant_id: merchant, order_id: orderId};
}

// Composite key via nested Maps: no string concatenation, so values containing
// any delimiter (including NUL) can never collide across merchants/orders.
const groupKey = (merchant, order, currency) => JSON.stringify([merchant, order, currency]);

function compareOrders(a, b) {
  const m = a.merchant_id.localeCompare(b.merchant_id, 'en');
  if (m !== 0) return m;
  const o = a.order_id.localeCompare(b.order_id, 'en');
  if (o !== 0) return o;
  return a.currency.localeCompare(b.currency, 'en');
}

function statusOf(rec, refundWindowOpen) {
  const principal = rec.captured_minor;
  const consumed = rec.refunded_minor + rec.chargeback_minor;
  if (consumed >= principal) {
    return rec.chargeback_minor > 0 ? 'charged_back' : 'refunded';
  }
  return 'paid';
}

export function reconcile(events, options = {}) {
  const opts = normalizeOptions(options);

  const list = events === undefined || events === null ? [] : events;
  if (!Array.isArray(list)) throw new Error('INVALID_EVENTS: events must be an array');

  const result = {
    totals: ZERO_TOTALS(),
    orders: [],
    accepted_ids: [],
    duplicate_ids: [],
    deferred_ids: [],
    rejected: [],
  };

  const groups = new Map();
  // Idempotency is scoped per merchant: (merchant_id, trimmed id).
  const seenKeys = new Set();
  const idemKey = (merchant, id) => JSON.stringify([merchant, id]);

  // Process in stable time order (ties keep input position); field validation
  // stays in input order so validation errors are reported deterministically.
  const checked = [];
  for (let i = 0; i < list.length; i++) {
    const check = validateEvent(list[i], opts);
    if (!check.ok) {
      result.rejected.push({event_id: check.event_id, code: check.code});
      continue;
    }
    checked.push({...check, _pos: i});
  }
  checked.sort((a, b) => (a.at - b.at) || (a._pos - b._pos));

  for (const check of checked) {
    const {id, type, amount, at, currency, merchant_id, order_id} = check;

    // Contract order: after field validation, screen future events first
    // ("再筛未来、幂等及业务约束"). Deferred events claim no idempotency slot.
    if (opts.as_of !== undefined && at > opts.as_of) {
      result.deferred_ids.push(id);
      continue;
    }

    // Idempotency: only a *successful* earlier event claims the key.
    const key2 = idemKey(merchant_id, id);
    if (seenKeys.has(key2)) {
      result.duplicate_ids.push(id);
      continue;
    }

    const key = groupKey(merchant_id, order_id, currency);
    let rec = groups.get(key);
    if (!rec) {
      rec = {
        merchant_id,
        order_id,
        currency,
        captured_minor: 0,
        refunded_minor: 0,
        fee_minor: 0,
        chargeback_minor: 0,
        net_minor: 0,
        available_minor: 0,
        status: 'paid',
        _firstCaptureAt: null,
        _accepted: 0,
      };
      groups.set(key, rec);
    }

    if (type === 'capture') {
      rec.captured_minor += amount;
      if (rec._firstCaptureAt === null) rec._firstCaptureAt = at;
      // Automatic per-capture fee: floor each capture separately (fraud-safe),
      // never deducted from the refundable principal.
      if (opts.fee_bps > 0) {
        rec.fee_minor += floorBps(amount, opts.fee_bps);
      }
    } else if (rec._firstCaptureAt === null) {
      // No capture for this group yet (events are processed in time order).
      result.rejected.push({event_id: id, code: 'NO_CAPTURE'});
      continue;
    } else if (type === 'refund') {
      // Refund window: first capture of this order -> refund, inclusive boundary.
      // Time is checked before any amount/principal constraint ("先时间后超额").
      const windowMs = opts.refund_window_hours * 3600 * 1000;
      if (at - rec._firstCaptureAt > windowMs) {
        result.rejected.push({event_id: id, code: 'REFUND_WINDOW'});
        continue;
      }
      // Cumulative refunds may not exceed capture - refund - chargeback.
      // Fees never reduce this refundable principal.
      const refundable = rec.captured_minor - rec.refunded_minor - rec.chargeback_minor;
      if (amount > refundable) {
        result.rejected.push({event_id: id, code: 'OVER_REFUND'});
        continue;
      }
      rec.refunded_minor += amount;
    } else if (type === 'fee') {
      rec.fee_minor += amount;
    } else if (type === 'chargeback') {
      // Chargebacks share the same principal as refunds: cumulative
      // refund + chargeback may not exceed the captured amount.
      const principalLeft = rec.captured_minor - rec.refunded_minor - rec.chargeback_minor;
      if (amount > principalLeft) {
        result.rejected.push({event_id: id, code: 'OVER_CHARGEBACK'});
        continue;
      }
      rec.chargeback_minor += amount;
    }

    // Successful event: claim the idempotency slot exactly once.
    seenKeys.add(key2);
    rec._accepted += 1;
    result.accepted_ids.push(id);
  }

  for (const rec of groups.values()) {
    if (rec._accepted === 0) continue;
    finalizeAmounts(rec, opts.reserve_bps);
    rec.status = statusOf(rec, true);
    delete rec._firstCaptureAt;
    delete rec._accepted;
    result.orders.push(rec);
  }
  result.orders.sort(compareOrders);

  for (const rec of result.orders) {
    for (const k of MONEY_KEYS) result.totals[k] += rec[k];
  }

  return result;
}

// ---------------------------------------------------------------------------
// CSV export
// CSV columns (fixed order): merchant_id,order_id,currency,captured_minor,
// refunded_minor,fee_minor,chargeback_minor,net_minor,available_minor
// A field is quoted only when it contains a comma, a double quote or a line
// break; inner double quotes are doubled. Numbers are emitted verbatim.
// Rows follow the already-sorted `result.orders` order. Line separator is LF.
const CSV_COLUMNS = [
  'merchant_id',
  'order_id',
  'currency',
  ...MONEY_KEYS,
];

function csvField(value) {
  const s = value === undefined || value === null ? '' : String(value);
  if (/[",\r\n]/.test(s)) return `"${s.replaceAll('"', '""')}"`;
  return s;
}

export function toCsv(result) {
  const orders = Array.isArray(result?.orders) ? result.orders : [];
  const lines = [CSV_COLUMNS.join(',')];
  for (const order of orders) {
    lines.push(CSV_COLUMNS.map((col) => csvField(order?.[col])).join(','));
  }
  return `${lines.join('\n')}\n`;
}

// ---------------------------------------------------------------------------
// Report summary
// Input: [{batch_id, result}]. The first record for each batch_id wins; later
// records with the same batch_id are ignored entirely (not summed). Returns
// {batch_count, batch_ids, totals} where batch_ids is sorted with the same
// pinned English locale used elsewhere, and totals sums the six money keys.
export function summarizeReports(reports) {
  const list = Array.isArray(reports) ? reports : [];
  const seen = new Set();
  const batchIds = [];
  const totals = ZERO_TOTALS();

  for (const entry of list) {
    const batchId = entry?.batch_id;
    if (typeof batchId !== 'string') continue;
    if (seen.has(batchId)) continue;
    seen.add(batchId);
    batchIds.push(batchId);

    const t = entry?.result?.totals;
    if (!t) continue;
    for (const k of MONEY_KEYS) {
      const v = t[k];
      if (typeof v === 'number' && Number.isFinite(v)) totals[k] += v;
    }
  }

  batchIds.sort((a, b) => a.localeCompare(b, 'en'));
  return {batch_count: batchIds.length, batch_ids: batchIds, totals};
}

