finalArtifacts.ledger.mjs:
import {pathToFileURL} from 'node:url';

const TYPES = new Set(['capture', 'refund', 'fee', 'chargeback']);
const AMOUNT_KEYS = [
  'captured_minor',
  'refunded_minor',
  'fee_minor',
  'chargeback_minor',
  'net_minor',
  'available_minor',
];

const DEFAULTS = {
  fee_bps: 0,
  reserve_bps: 0,
  refund_window_hours: 72,
  allowed_currencies: ['CNY'],
};

function isSafeNonNegativeInt(value) {
  return Number.isSafeInteger(value) && value >= 0;
}

function normalizeOptions(options) {
  if (options === undefined || options === null) options = {};
  if (typeof options !== 'object' || Array.isArray(options)) return null;
  const merged = {...DEFAULTS, ...options};
  if (!isSafeNonNegativeInt(merged.fee_bps) || merged.fee_bps > 10000) return null;
  if (!isSafeNonNegativeInt(merged.reserve_bps) || merged.reserve_bps > 10000) return null;
  if (!Number.isSafeInteger(merged.refund_window_hours) || merged.refund_window_hours <= 0) {
    return null;
  }
  if (
    !Array.isArray(merged.allowed_currencies) ||
    merged.allowed_currencies.some((c) => typeof c !== 'string' || c.trim() === '')
  ) {
    return null;
  }
  if (merged.as_of !== undefined && merged.as_of !== null) {
    if (typeof merged.as_of !== 'string') return null;
    if (!Number.isFinite(Date.parse(merged.as_of))) return null;
  }
  if (merged.allowed_merchants !== undefined && merged.allowed_merchants !== null) {
    if (
      !Array.isArray(merged.allowed_merchants) ||
      merged.allowed_merchants.some((m) => typeof m !== 'string' || m.trim() === '')
    ) {
      return null;
    }
  }
  return merged;
}

const TIME_WITH_ZONE = /(Z|[+-]\d{2}:?\d{2})$/;

function isValidTime(value) {
  return typeof value === 'string' && TIME_WITH_ZONE.test(value) && Number.isFinite(Date.parse(value));
}

function createBucket(merchantId, orderId, currency) {
  return {
    merchant_id: merchantId,
    order_id: orderId,
    currency,
    captured_minor: 0,
    refunded_minor: 0,
    fee_minor: 0,
    chargeback_minor: 0,
    net_minor: 0,
    available_minor: 0,
    status: 'paid',
    captureCount: 0,
    firstCaptureMs: null,
  };
}

function idSortKey(value) {
  return typeof value === 'string' ? value : '';
}

export function reconcile(events, options = {}) {
  const opts = normalizeOptions(options);
  if (opts === null) throw new Error('INVALID_OPTIONS');
  const events0 = events === undefined || events === null ? [] : events;
  if (!Array.isArray(events0)) throw new Error('INVALID_OPTIONS');

  const allowedCurrencies = new Set(opts.allowed_currencies.map((c) => c.trim().toUpperCase()));
  const allowedMerchants =
    Array.isArray(opts.allowed_merchants) && opts.allowed_merchants.length > 0
      ? new Set(opts.allowed_merchants.map((m) => m.trim()))
      : null;
  const asOfMs = opts.as_of ? Date.parse(opts.as_of) : null;

  const totals = Object.fromEntries(AMOUNT_KEYS.map((k) => [k, 0]));
  const acceptedIds = [];
  const duplicateIds = [];
  const deferredIds = [];
  const rejected = [];
  const seenIdKeys = new Set();
  const buckets = new Map();

  // Phase 1: format validation in input order, collect valid candidates.
  const candidates = [];
  for (let index = 0; index < events0.length; index += 1) {
    const event = events0[index] && typeof events0[index] === 'object' ? events0[index] : {};
    const rawId = typeof event.id === 'string' ? event.id : '';
    const id = rawId.trim();
    const merchantId = typeof event.merchant_id === 'string' ? event.merchant_id.trim() : '';
    if (id === '' || merchantId === '') {
      rejected.push({event_id: id, code: 'INVALID_ID'});
      continue;
    }
    const type = event.type;
    if (typeof type !== 'string' || !TYPES.has(type)) {
      rejected.push({event_id: id, code: 'INVALID_TYPE'});
      continue;
    }
    if (!Number.isSafeInteger(event.amount_minor) || event.amount_minor <= 0) {
      rejected.push({event_id: id, code: 'INVALID_AMOUNT'});
      continue;
    }
    if (!isValidTime(event.at)) {
      rejected.push({event_id: id, code: 'INVALID_TIME'});
      continue;
    }
    const currency = typeof event.currency === 'string' ? event.currency.trim().toUpperCase() : '';
    if (currency === '' || !allowedCurrencies.has(currency)) {
      rejected.push({event_id: id, code: 'UNSUPPORTED_CURRENCY'});
      continue;
    }
    if (allowedMerchants && !allowedMerchants.has(merchantId)) {
      rejected.push({event_id: id, code: 'UNSUPPORTED_MERCHANT'});
      continue;
    }
    candidates.push({
      id,
      merchantId,
      type,
      amount: event.amount_minor,
      atMs: Date.parse(event.at),
      orderId: typeof event.order_id === 'string' ? event.order_id.trim() : '',
      currency,
      index,
    });
  }

  // Phase 2: stable sort by time, ties keep input position.
  candidates.sort((a, b) => a.atMs - b.atMs || a.index - b.index);

  for (const candidate of candidates) {
    const {id, merchantId, type, amount, atMs, orderId, currency} = candidate;
    if (asOfMs !== null && atMs > asOfMs) {
      deferredIds.push(id);
      continue;
    }
    const key = `${merchantId}\u0000${orderId}\u0000${currency}`;
    let bucket = buckets.get(key);
    if (!bucket) {
      bucket = createBucket(merchantId, orderId, currency);
      buckets.set(key, bucket);
    }

    if (type !== 'capture' && bucket.captured_minor <= 0) {
      rejected.push({event_id: id, code: 'NO_CAPTURE'});
      continue;
    }
    if (type === 'refund') {
      const windowMs = opts.refund_window_hours * 3600 * 1000;
      if (atMs - bucket.firstCaptureMs > windowMs) {
        rejected.push({event_id: id, code: 'REFUND_WINDOW'});
        continue;
      }
      const refundable =
        bucket.captured_minor - bucket.refunded_minor - bucket.chargeback_minor;
      if (amount > refundable) {
        rejected.push({event_id: id, code: 'OVER_REFUND'});
        continue;
      }
    }
    if (type === 'chargeback') {
      const remaining = bucket.captured_minor - bucket.refunded_minor - bucket.chargeback_minor;
      if (amount > remaining) {
        rejected.push({event_id: id, code: 'OVER_CHARGEBACK'});
        continue;
      }
    }

    const idemKey = `${merchantId}\u0000${id}`;
    if (seenIdKeys.has(idemKey)) {
      duplicateIds.push(id);
      continue;
    }
    seenIdKeys.add(idemKey);

    if (type === 'capture') {
      bucket.captured_minor += amount;
      bucket.captureCount += 1;
      bucket.fee_minor += Math.floor((amount * opts.fee_bps) / 10000);
      bucket.firstCaptureMs =
        bucket.firstCaptureMs === null ? atMs : Math.min(bucket.firstCaptureMs, atMs);
    } else if (type === 'refund') {
      bucket.refunded_minor += amount;
    } else if (type === 'fee') {
      bucket.fee_minor += amount;
    } else {
      bucket.chargeback_minor += amount;
    }
    acceptedIds.push(id);
  }

  const orders = [];
  const sortedBuckets = [...buckets.values()].sort((a, b) => {
    const m = a.merchant_id.localeCompare(b.merchant_id, 'en');
    if (m !== 0) return m;
    const o = a.order_id.localeCompare(b.order_id, 'en');
    if (o !== 0) return o;
    return a.currency.localeCompare(b.currency, 'en');
  });

  for (const bucket of sortedBuckets) {
    const hasSuccess =
      bucket.captured_minor > 0 ||
      bucket.refunded_minor > 0 ||
      bucket.fee_minor > 0 ||
      bucket.chargeback_minor > 0;
    if (!hasSuccess) continue;
    const net =
      bucket.captured_minor - bucket.refunded_minor - bucket.chargeback_minor - bucket.fee_minor;
    const reserveBase = Math.max(net, 0);
    const reserve = Math.floor((reserveBase * opts.reserve_bps) / 10000);
    const available = net - reserve;
    let status = 'paid';
    if (
      bucket.captured_minor > 0 &&
      bucket.refunded_minor + bucket.chargeback_minor >= bucket.captured_minor
    ) {
      status = bucket.chargeback_minor > 0 ? 'charged_back' : 'refunded';
    }
    orders.push({
      merchant_id: bucket.merchant_id,
      order_id: bucket.order_id,
      currency: bucket.currency,
      captured_minor: bucket.captured_minor,
      refunded_minor: bucket.refunded_minor,
      fee_minor: bucket.fee_minor,
      chargeback_minor: bucket.chargeback_minor,
      net_minor: net,
      available_minor: available,
      status,
    });
    totals.captured_minor += bucket.captured_minor;
    totals.refunded_minor += bucket.refunded_minor;
    totals.fee_minor += bucket.fee_minor;
    totals.chargeback_minor += bucket.chargeback_minor;
    totals.net_minor += net;
    totals.available_minor += available;
  }

  return {
    totals,
    orders,
    accepted_ids: acceptedIds,
    duplicate_ids: duplicateIds,
    deferred_ids: deferredIds,
    rejected,
  };
}

const CSV_COLUMNS = [
  'merchant_id',
  'order_id',
  'currency',
  'captured_minor',
  'refunded_minor',
  'fee_minor',
  'chargeback_minor',
  'net_minor',
  'available_minor',
];

function csvCell(value) {
  const text = value === undefined || value === null ? '' : String(value);
  if (/[",\r\n]/.test(text)) {
    return `"${text.replaceAll('"', '""')}"`;
  }
  return text;
}

export function toCsv(result) {
  const orders = Array.isArray(result?.orders) ? result.orders : [];
  const lines = [CSV_COLUMNS.join(',')];
  for (const order of orders) {
    lines.push(CSV_COLUMNS.map((column) => csvCell(order?.[column])).join(','));
  }
  return lines.join('\n') + '\n';
}

export function summarizeReports(reports) {
  const list = Array.isArray(reports) ? reports : [];
  const seen = new Set();
  const totals = Object.fromEntries(AMOUNT_KEYS.map((k) => [k, 0]));
  for (const report of list) {
    const batchId = report && typeof report.batch_id === 'string' ? report.batch_id : '';
    if (seen.has(batchId)) continue;
    seen.add(batchId);
    const reportTotals = report?.result?.totals;
    for (const key of AMOUNT_KEYS) {
      totals[key] += Number.isSafeInteger(reportTotals?.[key]) ? reportTotals[key] : 0;
    }
  }
  const batchIds = [...seen].sort((a, b) => a.localeCompare(b, 'en'));
  return {batch_count: batchIds.length, batch_ids: batchIds, totals};
}

export default reconcile;
void idSortKey;
void pathToFileURL;

