#!/usr/bin/env node
import {readFile, writeFile} from 'node:fs/promises';
import {reconcile} from './ledger.mjs';

function usage() {
  return 'usage: node cli.mjs input.json [output.json]';
}

async function main(argv) {
  const args = argv.slice(2);
  if (args.length < 1 || args.length > 2) {
    process.stderr.write(usage() + '\n');
    process.exitCode = 2;
    return;
  }
  const [inputPath, outputPath] = args;

  let document;
  try {
    document = JSON.parse(await readFile(inputPath, 'utf8'));
  } catch (error) {
    process.stderr.write(`cli: cannot read input ${inputPath}: ${error.message}\n`);
    process.exitCode = 1;
    return;
  }
  if (document === null || typeof document !== 'object' || Array.isArray(document)) {
    process.stderr.write('cli: input must be a JSON object with events/options\n');
    process.exitCode = 1;
    return;
  }

  const events = document.events === undefined ? [] : document.events;
  const options = document.options === undefined ? {} : document.options;

  let result;
  try {
    result = reconcile(events, options);
  } catch (error) {
    process.stderr.write(`cli: ${error.message}\n`);
    process.exitCode = 1;
    return;
  }

  const json = JSON.stringify(result, null, 2) + '\n';
  if (outputPath === undefined) {
    process.stdout.write(json);
    return;
  }
  try {
    await writeFile(outputPath, json, 'utf8');
  } catch (error) {
    process.stderr.write(`cli: cannot write output ${outputPath}: ${error.message}\n`);
    process.exitCode = 1;
  }
}

main(process.argv);

