function deepFreeze(v, seen = new WeakSet()) {
  if (v === null || typeof v !== 'object' || seen.has(v)) return v;
  seen.add(v); Object.freeze(v);
  for (const k of Reflect.ownKeys(v)) deepFreeze(v[k], seen);
  return v;
}

