{"command":"cd <TEMP_ROOT>/memweave/workspace && node -e "
import('node:fs/promises').then(async ({readdir,readFile})=>{
  const {execFile}=await import('node:child_process');
  const {promisify}=await import('node:util');
  const {createHash}=await import('node:crypto');
  const run=promisify(execFile);
  const sha=b=>createHash('sha256').update(b).digest('hex');
  const files=(await readdir('batches')).filter(f=>/^B0\d\d\.json$/.test(f)).sort();
  const pre={};
  for(const f of files) pre[f]=sha(await readFile('batches/'+f));
  let nonIdem=[];
  for(const f of files){
    const id=f.replace('.json','');
    const o1='/tmp/i1-'+id+'.json', o2='/tmp/i2-'+id+'.json', o3='/tmp/i3-'+id+'.json';
    await run('node',['cli.mjs','batches/'+f,o1]);
    await run('node',['cli.mjs','batches/'+f,o2]);
    await run('node',['cli.mjs','batches/'+f,o3]);
    const a=await readFile(o1,'utf8'), b=await readFile(o2,'utf8'), c=await readFile(o3,'utf8');
    if(!(a===b && b===c)) nonIdem.push(id);
  }
  let changed=[];
  for(const f of files) if(sha(await readFile('batches/'+f))!==pre[f]) changed.push(f);
  console.log('批次数:', files.length);
  console.log('三次重跑输出完全一致:', nonIdem.length===0, '| 不一致批次:', nonIdem);
  console.log('原始输入未被修改:', changed.length===0, '| 变动:', changed);
});
""}
